message.content:
{
  "description": "The image shows a single large, robust felid standing in profile on a plain off-white background with a soft gray shadow beneath its feet, facing to the right with its head turned three-quarters toward the viewer. It has a muscular, deep-chested body covered in short dense tawny golden-brown fur that is paler cream-white on the chin, chest, belly and inner legs, with faint to moderate dark brown striping and spotting across the body. The head is broad with a short muzzle, the neck and chest bear longer shaggy fur forming a ruff, and the limbs are thick and sturdy ending in large rounded paws. A short thin tail with dark banding and a dark tip extends from the rear. The overall stance is calm and alert, with all four feet on the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "large broad felid head with a short muzzle, pinkish-brown nose, white fur on the chin, lower lip and whisker pads, long white whiskers on the muzzle, amber-brown eyes with white patches and dark outlines below, and a forehead with faint dark spots and short stripes",
      "where": "at the anterior/front end of the body, turned slightly toward the viewer"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with tawny fur, lighter fur on the edges and inside, and a distinct dark blackish patch on the back of each ear",
      "where": "on top of the head, set wide apart"
    },
    {
      "part": "mane",
      "looks_like": "longer shaggy fur forming a ruff, tawny on the sides of the neck and paler cream-white and more elongated on the throat and central chest, with a slightly tousled texture",
      "where": "around the neck, throat and upper chest, extending down the front of the chest"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in tawny fur with darker horizontal transverse stripes, most distinct on the lower segments, especially the hind legs; forelimbs are straight and vertical, hindlimbs are angled at the hock",
      "where": "beneath the body, two forelimbs under the chest and two hindlimbs under the hindquarters"
    },
    {
      "part": "feet",
      "looks_like": "four large rounded paws with visible toe lobes and short dark claws, fur lighter on the paws, front paws viewed frontally and larger, hind paws viewed in profile",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short slender tail covered in tawny fur with dark transverse bands and a dark bushy tip that is blackish with a small white patch",
      "where": "extending from the dorsal posterior end of the body at the hindquarters, hanging down and slightly to the left"
    },
    {
      "part": "markings",
      "looks_like": "faint to moderately distinct dark brown to black transverse stripes and small spots, more concentrated and darker on the lower hind legs, hindquarters and lower forelimbs, fainter and diffuse along the back, sides and torso, with small spots and short stripes on the forehead and face",
      "where": "distributed across the body, head, legs and tail, most visible on the legs and rear"
    }
  ],
  "attached_objects": [],
  "animals": ["lion", "tiger"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
